import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BCectEOt.js";const h=JSON.parse('{"title":"Privacy Policy","description":"Privacy policy for the Sapphire Star Codex apps and website: local data, backups, support messages, deletion and contact.","frontmatter":{"description":"Privacy policy for the Sapphire Star Codex apps and website: local data, backups, support messages, deletion and contact.","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/privacy/"}],["meta",{"property":"og:title","content":"Privacy Policy | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Privacy policy for the Sapphire Star Codex apps and website: local data, backups, support messages, deletion and contact."}]]},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),i={name:"privacy/index.md"};function s(n,e,c,l,d,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>Effective and last updated: October 31, 2026</p><p>This policy covers Sapphire Star Codex, its iOS, Android and HarmonyOS apps, and this website. The developer is <strong>eurekaffeine (刘耀晨)</strong>. Privacy questions can be sent to <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>.</p><p>The apps are in development and features vary by platform. The practices described here apply to the current apps and website. You do not need an account to use the app.</p><h2 id="data-kept-on-your-device" tabindex="-1">Data kept on your device <a class="header-anchor" href="#data-kept-on-your-device" aria-label="Permalink to &quot;Data kept on your device&quot;">​</a></h2><p>The app keeps data locally to remember your choices and provide its features. Depending on the platform and features you use, this includes:</p><ul><li>Your selected game, language, appearance and other preferences.</li><li>Search history and browsing state used to resume a screen.</li><li>Saved monsters, equipment and other reference entries.</li><li>Saved builds, custom build names, decoration counts, talismans and armor inventory.</li></ul><p>The app uses this information for browsing, search, saved entries and equipment planning. It does not upload these records to the developer or operate a developer-run account or cloud-sync service.</p><h2 id="permissions-and-automatic-collection" tabindex="-1">Permissions and automatic collection <a class="header-anchor" href="#permissions-and-automatic-collection" aria-label="Permalink to &quot;Permissions and automatic collection&quot;">​</a></h2><p>The current apps do not include advertising, tracking, analytics or automatic crash-upload SDKs. They do not ask for access to your contacts, location, camera, microphone or photo library for their current features, and do not collect advertising identifiers.</p><p>Your operating system or app store may separately process installation and diagnostic information under its own settings and policies. If a platform makes diagnostics available to us, we use them to investigate app issues.</p><h2 id="when-you-contact-us" tabindex="-1">When you contact us <a class="header-anchor" href="#when-you-contact-us" aria-label="Permalink to &quot;When you contact us&quot;">​</a></h2><p>If you email us, we receive your email address, the message and any attachments you choose to send. We use that information to answer you, investigate reported problems and handle privacy requests. Please include only what is needed for your request. We do not use support correspondence for advertising or mailing lists.</p><h2 id="website-backups-and-other-services" tabindex="-1">Website, backups and other services <a class="header-anchor" href="#website-backups-and-other-services" aria-label="Permalink to &quot;Website, backups and other services&quot;">​</a></h2><p><strong>Website.</strong> This site is hosted on GitHub Pages. We do not add analytics, advertising cookies or tracking pixels. Site search runs in your browser, and display/search preferences may be stored there. GitHub receives technical request information when you visit, such as your IP address and browser details. Its handling is described in <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub’s privacy statement</a>.</p><p><strong>Device backups.</strong> Your operating system may include app data in device or cloud backups, depending on your settings. Those backups are managed by your platform provider, not by us. We cannot access or delete them for you.</p><p><strong>Email and external links.</strong> Our support mailbox uses Gmail; messages are processed by Google to provide email services under <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google’s privacy policy</a>. External websites and app stores apply their own privacy policies when you open them. Hosting, email and backup providers may process information in countries other than yours.</p><h2 id="sharing-retention-and-deletion" tabindex="-1">Sharing, retention and deletion <a class="header-anchor" href="#sharing-retention-and-deletion" aria-label="Permalink to &quot;Sharing, retention and deletion&quot;">​</a></h2><p>We do not sell or rent your personal information, or share it for advertising. Information you send us is handled through the email provider described above. We may disclose information we actually hold when required by law or when you specifically ask us to do so.</p><ul><li><strong>Local app data</strong> stays until you remove it using available app controls or device settings. To remove local data, use the device option that deletes the app and its data. Offloading or archiving may keep that data. Backups can remain separately and may restore data when you reinstall.</li><li><strong>Website preferences</strong> remain in your browser until you clear this site’s stored data or your browser removes it.</li><li><strong>Support messages and shared diagnostics</strong> are kept only while needed to handle and follow up on the issue, or to meet a legal obligation. You can ask us to delete information you sent us, unless we are legally required to retain it.</li><li><strong>Provider-held data</strong>, including backups and hosting logs, is subject to the provider’s retention rules and controls.</li></ul><p>To request access to, correction of or deletion of information you sent us, use the contact address below. We cannot remotely access or erase records stored only on your device.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Local app data uses the operating system’s application storage protections. This website uses HTTPS. We limit access to support correspondence to handling support and privacy requests, using the email provider’s security controls.</p><h2 id="children-s-privacy" tabindex="-1">Children’s privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children’s privacy&quot;">​</a></h2><p>The app does not require a personal profile or date of birth, and we do not knowingly solicit personal information from children. If a parent or guardian believes a child has sent us personal information, please contact us so we can address its removal.</p><h2 id="policy-changes" tabindex="-1">Policy changes <a class="header-anchor" href="#policy-changes" aria-label="Permalink to &quot;Policy changes&quot;">​</a></h2><p>We will update this page and its date when our practices change. Material changes will be explained on the website or in the app’s release information. If a new feature needs a separate permission or consent, it will ask for it; this policy does not grant that permission by itself.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Developer: <strong>eurekaffeine (刘耀晨)</strong><br> App: <strong>Sapphire Star Codex</strong><br> Email: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',29)])])}const y=a(i,[["render",s]]);export{h as __pageData,y as default};
